import { gsap } from "gsap";
import { useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import { LANDING_PRELOAD, LANDING_WARM } from "./landingContent";

/**
 * The loading gate in front of the landing.
 *
 * It is not decorative: it holds the page until the fonts and the images the
 * FIRST frame paints are decoded, so the hero never starts its entrance and
 * then reflows. The bar reports that work — it is driven by `loaded / total`,
 * floored by a minimum dwell so a warm cache does not flash a bar from 0 to
 * 100 in two frames, and capped so a dead request can never strand the reader
 * on it.
 *
 * Only LANDING_PRELOAD is awaited. The covers the shelf act uses are warmed
 * in the background (LANDING_WARM) but deliberately not counted: they are
 * four acts away, and a gate that waits for them is a gate that makes the
 * reader watch a bar fill for pictures they cannot see yet.
 */

/** Shortest time the gate stays up, so the hand-off reads as a beat of the
 *  piece rather than a flicker. Warm visits get the shorter floor. */
const MIN_MS_COLD = 1500;
const MIN_MS_WARM = 460;
/** Hard ceiling: past this the gate lifts whatever the network is doing. */
const MAX_MS = 6000;
/** How long the faces get before the gate stops waiting for them. */
const FONT_BUDGET_MS = 900;

const SESSION_KEY = "inkflow.landing.loaded";

const WORDMARK = "INKFLOW";

type GatePhase = "loading" | "leaving";

export function LoadingGate({ onDone }: { onDone: () => void }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const barRef = useRef<HTMLSpanElement>(null);
  const percentRef = useRef<HTMLSpanElement>(null);
  const [phase, setPhase] = useState<GatePhase>("loading");

  // A second visit in the same session already has the covers in the HTTP
  // cache; the gate still appears (it is part of the sequence) but stops
  // asking the reader to wait for work that is already done.
  const warm =
    typeof sessionStorage !== "undefined" &&
    sessionStorage.getItem(SESSION_KEY) === "1";

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    const minMs = warm ? MIN_MS_WARM : MIN_MS_COLD;
    const started = performance.now();

    // Reduced motion: no entrance beats, and the wait is cut to the floor.
    // The gate still reports real progress so it is not a lie, just quiet.
    const animate = !prefersReducedMotion;

    let fontsDone = false;
    let fontBudget = 0;
    let imagesDone = 0;
    const total: number = LANDING_PRELOAD.length;

    // `document.fonts.ready` resolves once every face the page references has
    // loaded. It never rejects — and it never resolves either, if the host
    // serving the faces is unreachable. That is not hypothetical here: on a
    // network where fonts.googleapis.com is blocked, `ready` hangs for the
    // whole page load, and a gate that awaits it unconditionally burns its
    // full ceiling every single visit. Fonts get a short budget; past that the
    // gate proceeds without them, which is what `display=swap` has the browser
    // do anyway.
    if (typeof document !== "undefined" && document.fonts) {
      void document.fonts.ready.then(() => {
        fontsDone = true;
      });
      fontBudget = window.setTimeout(() => {
        fontsDone = true;
      }, FONT_BUDGET_MS);
    } else {
      fontsDone = true;
    }

    LANDING_PRELOAD.forEach((src) => {
      const image = new Image();
      const settle = () => {
        imagesDone += 1;
      };
      image.onload = settle;
      image.onerror = settle;
      image.src = src;
    });

    // Fire-and-forget: these belong to act 04, so they are fetched on the
    // gate's idle time but never counted toward the bar. The gate's promise
    // is "the first frame is ready", not "the whole page is".
    LANDING_WARM.forEach((src) => {
      const image = new Image();
      image.src = src;
    });

    /** 0..1 of the real work finished. Fonts are half the budget — they are
     *  what the hero's first frame depends on — and the covers split the rest
     *  so the bar keeps moving while the last one is in flight. */
    const workRatio = () => {
      const fontShare = fontsDone ? 0.5 : 0;
      const imageShare = total === 0 ? 0.5 : 0.5 * (imagesDone / total);
      return fontShare + imageShare;
    };

    let shown = 0;
    let raf = 0;
    let finished = false;

    const tick = () => {
      const elapsed = performance.now() - started;
      const timeRatio = Math.min(elapsed / minMs, 1);
      const forced = elapsed >= MAX_MS ? 1 : 0;
      // Both gates must open: the work must be done AND the floor must have
      // passed. The ceiling overrides both.
      const target = forced || Math.min(workRatio(), timeRatio);

      // Ease toward the target so a burst of parallel loads does not snap the
      // bar forward, and never let it walk backwards.
      shown += (target - shown) * (target > shown ? 0.18 : 0.32);
      if (target >= 1 && 1 - shown < 0.004) shown = 1;

      if (barRef.current) {
        barRef.current.style.transform = `scaleX(${shown.toFixed(4)})`;
      }
      if (percentRef.current) {
        percentRef.current.textContent = String(
          Math.min(100, Math.round(shown * 100)),
        ).padStart(3, "0");
      }

      if (shown >= 1 && !finished) {
        finished = true;
        setPhase("leaving");
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    if (animate) {
      // fromTo, not from, and this is load-bearing. The CSS sets each of these
      // to its "before" state (letters at translateY(118%) inside an
      // overflow:hidden mask, staff lines at scaleX(0)) so the pre-JS frame
      // does not flash the finished wordmark. `gsap.from` animates FROM the
      // values you give it TO the element's current values — and the current
      // value is already the "before" state, so it animates 118% to 118% and
      // the wordmark stays clipped out of sight forever. Stating both ends
      // removes the dependency on what the element happens to be showing.
      // `y` as well as `yPercent`, and both ends: GSAP reads the CSS
      // `translateY(118%)` back as a PIXEL `y` (118% of the glyph's height)
      // rather than as a percentage, so a tween that only zeroes `yPercent`
      // still settles on a 58px offset and leaves the wordmark clipped.
      gsap.fromTo(
        root.querySelectorAll(".landing-load__letter-glyph"),
        { yPercent: 118, y: 0, rotate: 3 },
        {
          yPercent: 0,
          y: 0,
          rotate: 0,
          duration: 0.62,
          stagger: 0.036,
          ease: "power3.out",
          delay: 0.06,
        },
      );
      // fromTo here for the same reason: with `from`, an element whose
      // captured current opacity already reads 0 ends the tween where it
      // started and never appears. The meta block — the bar and the counter,
      // the whole point of the gate — was landing in exactly that state while
      // its sibling label animated normally.
      gsap.fromTo(
        root.querySelectorAll(".landing-load__fade"),
        { opacity: 0, y: 14 },
        {
          opacity: 1,
          y: 0,
          duration: 0.5,
          stagger: 0.08,
          ease: "power2.out",
          delay: 0.34,
        },
      );
      gsap.fromTo(
        root.querySelectorAll(".landing-load__staff-line"),
        { scaleX: 0 },
        {
          scaleX: 1,
          duration: 0.7,
          stagger: 0.06,
          ease: "power2.out",
          transformOrigin: "left center",
        },
      );
    }

    raf = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(fontBudget);
    };
  }, [prefersReducedMotion, warm]);

  // The exit runs as its own effect so it starts from a committed "leaving"
  // render, and so the reveal is never racing the still-running entrance.
  useEffect(() => {
    if (phase !== "leaving") return undefined;
    const root = rootRef.current;
    if (!root) return undefined;

    sessionStorage.setItem(SESSION_KEY, "1");

    const finish = () => onDone();

    if (prefersReducedMotion) {
      const timer = window.setTimeout(finish, 180);
      return () => window.clearTimeout(timer);
    }

    const exit = gsap.timeline({ onComplete: finish });
    exit
      .to(root.querySelectorAll(".landing-load__fade, .landing-load__staff"), {
        opacity: 0,
        y: -22,
        duration: 0.42,
        stagger: 0.05,
        ease: "power2.in",
      })
      .to(
        root.querySelector(".landing-load__veil"),
        {
          // Same ellipse motif the room's own curtain opens with, so the
          // landing and the shelf read as one room seen twice.
          clipPath: "ellipse(0% 0% at 50% 62%)",
          duration: 0.72,
          ease: "power3.inOut",
        },
        "-=0.2",
      )
      .to(root, { autoAlpha: 0, duration: 0.22 }, "-=0.1");

    return () => {
      exit.kill();
    };
  }, [phase, prefersReducedMotion, onDone]);

  return (
    <div
      ref={rootRef}
      className="landing-load"
      data-phase={phase}
      role="status"
      aria-live="polite"
      aria-label="正在布置房间"
    >
      <div className="landing-load__veil">
        <div className="landing-load__staff" aria-hidden="true">
          {Array.from({ length: 5 }, (_, index) => (
            <i key={index} className="landing-load__staff-line" />
          ))}
        </div>
        <span className="landing-load__note" aria-hidden="true">
          ♪
        </span>
      </div>

      <div className="landing-load__copy">
        <span className="landing-load__word">
          {WORDMARK.split("").map((letter, index) => (
            <span key={`${letter}-${index}`} className="landing-load__letter">
              <i className="landing-load__letter-glyph">{letter}</i>
            </span>
          ))}
        </span>

        <span className="landing-load__meta landing-load__fade">
          <span className="landing-load__bar">
            <span ref={barRef} className="landing-load__bar-fill" />
          </span>
          <span className="landing-load__counter">
            <span ref={percentRef}>000</span>
            <em>%</em>
          </span>
        </span>

        <span className="landing-load__label landing-load__fade">
          正在布置房间 · Shelving the room
        </span>
      </div>
    </div>
  );
}
