import { z } from "zod";

export const SourceSpanSchema = z.object({
  noteId: z.string(),
  pageId: z.string(),
  blockId: z.string().optional(),
  strokeId: z.string().optional(),
  start: z.number().int().nonnegative().optional(),
  end: z.number().int().nonnegative().optional(),
});

export type SourceSpan = z.infer<typeof SourceSpanSchema>;

export const LanguageInsightSchema = z.object({
  term: z.string().min(1),
  lemma: z.string().min(1),
  meaningsZh: z.array(z.string().min(1)).min(1),
  definitionEn: z.string().min(1),
  pronunciation: z.string().optional(),
  partOfSpeech: z.string().optional(),
  cefr: z.string().optional(),
  collocations: z.array(z.string()).default([]),
  examples: z
    .array(
      z.object({
        text: z.string(),
        translationZh: z.string().optional(),
      }),
    )
    .default([]),
  usageNotes: z.array(z.string()).default([]),
  sourceSpan: SourceSpanSchema.optional(),
  provider: z.enum(["deepseek", "mock", "dictionary"]).default("mock"),
  model: z.string().optional(),
  cached: z.boolean().optional(),
});

export type LanguageInsight = z.infer<typeof LanguageInsightSchema>;

export const AnalyzeSelectionRequestSchema = z.object({
  noteId: z.string().min(1),
  pageId: z.string().default("page-1"),
  blockId: z.string().optional(),
  strokeId: z.string().optional(),
  selectedText: z.string().trim().min(1).max(500),
  contextBefore: z.string().max(600).optional(),
  contextAfter: z.string().max(600).optional(),
  locale: z.string().default("zh-CN"),
  sourceSpan: SourceSpanSchema.optional(),
});

export type AnalyzeSelectionRequest = z.infer<typeof AnalyzeSelectionRequestSchema>;

export const CollocationRequestSchema = z.object({
  term: z.string().min(1).max(200),
  context: z.string().max(1200).optional(),
});

export const CollocationResponseSchema = z.object({
  term: z.string(),
  collocations: z.array(z.string()).min(1),
  provider: z.enum(["deepseek", "mock"]),
  model: z.string().optional(),
});

export type CollocationResponse = z.infer<typeof CollocationResponseSchema>;

export const CorpusEntrySchema = z.object({
  id: z.string(),
  term: z.string(),
  normalizedTerm: z.string(),
  meaningsZh: z.array(z.string()),
  definitionEn: z.string(),
  collocations: z.array(z.string()),
  source: SourceSpanSchema,
  sourceLabel: z.string(),
  tags: z.array(z.string()),
  favorite: z.boolean().default(false),
  createdAt: z.string(),
});

export type CorpusEntry = z.infer<typeof CorpusEntrySchema>;

export const AddCorpusRequestSchema = z.object({
  insight: LanguageInsightSchema,
  sourceLabel: z.string().default("Academic Reading"),
  tags: z.array(z.string()).default([]),
});

export type AddCorpusRequest = z.infer<typeof AddCorpusRequestSchema>;

export const KwicHitSchema = z.object({
  id: z.string(),
  left: z.string(),
  keyword: z.string(),
  right: z.string(),
  term: z.string(),
  sourceLabel: z.string(),
  source: SourceSpanSchema,
});

export type KwicHit = z.infer<typeof KwicHitSchema>;

export const KwicResponseSchema = z.object({
  query: z.string(),
  hits: z.array(KwicHitSchema),
  total: z.number(),
});

export type KwicResponse = z.infer<typeof KwicResponseSchema>;

export const PracticeTurnRequestSchema = z.object({
  sessionId: z.string(),
  message: z.string().min(1).max(2000),
  targetExpressions: z.array(z.string()).default([]),
  scenario: z.string().default("You are the CEO. I am the interviewer."),
});

export type PracticeTurnRequest = z.infer<typeof PracticeTurnRequestSchema>;

export const PracticeTurnResponseSchema = z.object({
  sessionId: z.string(),
  reply: z.string(),
  replyZh: z.string(),
  explanationZh: z.string(),
  usedExpressions: z.array(z.string()),
  feedback: z.string(),
  suggestions: z.array(z.string()),
  completed: z.boolean(),
});

export type PracticeTurnResponse = z.infer<typeof PracticeTurnResponseSchema>;

export const NotePageSchema = z.object({
  id: z.string(),
  noteId: z.string(),
  title: z.string(),
  index: z.number().int().nonnegative(),
  width: z.number().positive().default(960),
  height: z.number().positive().default(1340),
  template: z.enum([
    "academic",
    "article",
    "vocabulary",
    "interview",
    "blank",
  ]),
  content: z.unknown(),
  version: z.number().int().positive().default(1),
  updatedAt: z.string(),
});

export type NotePage = z.infer<typeof NotePageSchema>;

export const PointSchema = z.tuple([z.number(), z.number(), z.number().optional()]);
export type StrokePoint = z.infer<typeof PointSchema>;

export const InkStrokeSchema = z.object({
  id: z.string(),
  pageId: z.string(),
  tool: z.enum(["pen", "marker", "highlighter", "eraser", "lasso"]),
  color: z.string(),
  size: z.number().positive(),
  points: z.array(PointSchema),
  opacity: z.number().min(0).max(1).default(1),
  inputType: z.enum(["pen", "touch", "mouse"]).optional(),
  tiltX: z.number().optional(),
  tiltY: z.number().optional(),
  startedAt: z.string().optional(),
  endedAt: z.string().optional(),
  createdAt: z.string(),
});

export type InkStroke = z.infer<typeof InkStrokeSchema>;

export const RoomObjectIdSchema = z.enum([
  "bookshelf",
  "notebook",
  "typewriter",
  "phrase-board",
  "lamp",
  "phonograph",
  "camera",
  "drawer",
  "plant",
]);

export type RoomObjectId = z.infer<typeof RoomObjectIdSchema>;

export const RoomObjectStateSchema = z.enum([
  "idle",
  "hover",
  "selected",
  "dragging",
  "focused",
]);

export type RoomObjectState = z.infer<typeof RoomObjectStateSchema>;

export const VisionNoteRequestSchema = z.object({
  noteId: z.string(),
  pageId: z.string(),
  imageUrl: z.string().optional(),
  imageBase64: z.string().optional(),
  mediaType: z.enum(["image/jpeg", "image/png", "image/webp", "image/gif"]).optional(),
  prompt: z.string().default(
    "Read this image as an English study note. Return useful expressions, context, and a short Chinese explanation.",
  ),
});

export type VisionNoteRequest = z.infer<typeof VisionNoteRequestSchema>;

export const VisionNoteResponseSchema = z.object({
  extractedText: z.string(),
  insights: z.array(LanguageInsightSchema),
  provider: z.enum(["deepseek", "mock"]),
  model: z.string().optional(),
});

export type VisionNoteResponse = z.infer<typeof VisionNoteResponseSchema>;

export const DocumentKeyPointSchema = z.object({
  heading: z.string().min(1),
  explanationZh: z.string().min(1),
  sourceQuote: z.string().optional(),
});

export type DocumentKeyPoint = z.infer<typeof DocumentKeyPointSchema>;

export const DocumentAnalysisRequestSchema = z.object({
  title: z.string().trim().default("Imported document"),
  text: z.string().trim().min(20).max(60_000),
  sourceLabel: z.string().trim().default("Imported document"),
  locale: z.string().default("zh-CN"),
});

export type DocumentAnalysisRequest = z.infer<
  typeof DocumentAnalysisRequestSchema
>;

export const DocumentAnalysisResponseSchema = z.object({
  title: z.string(),
  summaryZh: z.string(),
  overviewZh: z.string(),
  keyPoints: z.array(DocumentKeyPointSchema).default([]),
  keyExpressions: z.array(LanguageInsightSchema).default([]),
  readingTimeMinutes: z.number().positive().default(1),
  provider: z.enum(["deepseek", "mock"]),
  model: z.string().optional(),
});

export type DocumentAnalysisResponse = z.infer<
  typeof DocumentAnalysisResponseSchema
>;

export const AuthUserSchema = z.object({
  id: z.string(),
  displayName: z.string(),
  avatarUrl: z.string().optional(),
  phoneMasked: z.string().optional(),
  wechatBound: z.boolean().default(false),
});

export type AuthUser = z.infer<typeof AuthUserSchema>;

export const AuthSessionSchema = z.object({
  user: AuthUserSchema,
  accessToken: z.string(),
  refreshToken: z.string(),
  expiresAt: z.string(),
});

export type AuthSession = z.infer<typeof AuthSessionSchema>;

/**
 * 抽屉便条。三个抽屉（notes / materials / collection）共用一张表，
 * 每个抽屉最多 DRAWER_NOTE_LIMIT 条 —— 上限放在 shared 里，前端禁用按钮和
 * 后端拒绝写入用的是同一个数字，避免只拦住一边。
 */
export const DRAWER_IDS = ["notes", "materials", "collection"] as const;
export const DrawerIdSchema = z.enum(DRAWER_IDS);
export type ShelfDrawerId = z.infer<typeof DrawerIdSchema>;

export const DRAWER_NOTE_LIMIT = 3;

export const DrawerNoteSchema = z.object({
  id: z.string(),
  drawerId: DrawerIdSchema,
  title: z.string(),
  meta: z.string(),
  createdAt: z.string(),
});

export type DrawerNote = z.infer<typeof DrawerNoteSchema>;

export const CreateDrawerNoteRequestSchema = z.object({
  drawerId: DrawerIdSchema,
  title: z.string().trim().min(1).max(240),
  meta: z.string().trim().max(240).default(""),
  /** 客户端先生成的 id：离线添加的便条登录后按同一个 id 上传，不会重复。 */
  id: z.string().trim().min(1).max(120).optional(),
});

export type CreateDrawerNoteRequest = z.infer<
  typeof CreateDrawerNoteRequestSchema
>;

export const NoteSpaceSchema = z.object({
  id: z.string(),
  title: z.string(),
  description: z.string(),
  accent: z.string(),
  noteCount: z.number().int().nonnegative(),
  phraseCount: z.number().int().nonnegative(),
  updatedAt: z.string(),
});

export type NoteSpace = z.infer<typeof NoteSpaceSchema>;

export const AIModelProfileSchema = z.enum(["instant", "deep"]);
export type AIModelProfile = z.infer<typeof AIModelProfileSchema>;

