/**
 * 登录态。存的是服务端发的真会话（access token + 用户），不是假的占位用户。
 *
 * 没登录也能用整个书房 —— 抽屉便条这时只存在本机；登录之后同一份便条会跟着
 * 账号走。所以这里的每一种失败（服务器没开、token 过期、网络断）都只降级成
 * 「本机模式」，不阻塞界面。
 */
import { useCallback, useEffect, useState } from "react";
import type { AuthUser } from "@inkflow/shared";
import {
  ApiError,
  fetchAccount,
  loginDeveloper,
  requestSmsCode,
  signOutRemote,
  verifySmsCode,
} from "./accountApi";

const SESSION_STORAGE_KEY = "inkflow:account:v1";

export interface StoredSession {
  accessToken: string;
  refreshToken: string;
  expiresAt: string;
  user: AuthUser;
}

export type AccountStatus = "anonymous" | "signed-in";

function normalizeSession(value: unknown): StoredSession | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<StoredSession>;
  if (
    typeof candidate.accessToken !== "string" ||
    !candidate.accessToken ||
    !candidate.user ||
    typeof candidate.user.id !== "string"
  ) {
    return null;
  }
  return {
    accessToken: candidate.accessToken,
    refreshToken:
      typeof candidate.refreshToken === "string" ? candidate.refreshToken : "",
    expiresAt:
      typeof candidate.expiresAt === "string" ? candidate.expiresAt : "",
    user: candidate.user,
  };
}

export function loadStoredSession(): StoredSession | null {
  if (typeof localStorage === "undefined") return null;
  try {
    return normalizeSession(
      JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY) ?? "null"),
    );
  } catch {
    return null;
  }
}

function persistSession(session: StoredSession | null) {
  if (typeof localStorage === "undefined") return;
  try {
    if (session) {
      localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
    } else {
      localStorage.removeItem(SESSION_STORAGE_KEY);
    }
  } catch {
    // 隐私模式：登录还是有效，只是刷新后要重新登一次。
  }
}

function describeError(error: unknown) {
  if (error instanceof ApiError) {
    if (error.status === 401) return "验证码不对或已过期，请重新获取。";
    if (error.status === 400) return "手机号格式不对，请检查后重试。";
    return error.message;
  }
  return "连接不到服务器，便条先存在本机，联网后再登录即可同步。";
}

export function useInkflowAccount() {
  const [session, setSession] = useState<StoredSession | null>(loadStoredSession);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [devCode, setDevCode] = useState<string | null>(null);

  // 带着本地 token 回访时，跟服务器确认一次；确认不了就继续当本机模式用。
  useEffect(() => {
    const token = loadStoredSession()?.accessToken;
    if (!token) return;
    let cancelled = false;
    void fetchAccount(token)
      .then((payload) => {
        if (cancelled) return;
        setSession((current) => {
          if (!current || current.accessToken !== token) return current;
          const next = { ...current, user: payload.user };
          persistSession(next);
          return next;
        });
      })
      .catch((caught) => {
        if (cancelled || !(caught instanceof ApiError)) return;
        if (caught.status === 401) {
          persistSession(null);
          setSession(null);
          setError("登录已过期，请重新登录。");
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const adopt = useCallback((payload: StoredSession) => {
    persistSession(payload);
    setSession(payload);
    setError(null);
    setDevCode(null);
  }, []);

  const signInWithDeveloper = useCallback(async () => {
    setBusy(true);
    setError(null);
    try {
      adopt(await loginDeveloper());
      return true;
    } catch (caught) {
      setError(describeError(caught));
      return false;
    } finally {
      setBusy(false);
    }
  }, [adopt]);

  const sendCode = useCallback(async (phone: string) => {
    setBusy(true);
    setError(null);
    try {
      const result = await requestSmsCode(phone);
      setDevCode(result.devCode ?? null);
      return true;
    } catch (caught) {
      setError(describeError(caught));
      return false;
    } finally {
      setBusy(false);
    }
  }, []);

  const signInWithCode = useCallback(
    async (phone: string, code: string) => {
      setBusy(true);
      setError(null);
      try {
        adopt(await verifySmsCode(phone, code));
        return true;
      } catch (caught) {
        setError(describeError(caught));
        return false;
      } finally {
        setBusy(false);
      }
    },
    [adopt],
  );

  const signOut = useCallback(async () => {
    const token = session?.accessToken;
    persistSession(null);
    setSession(null);
    setError(null);
    setDevCode(null);
    if (!token) return;
    try {
      await signOutRemote(token);
    } catch {
      // 服务器没记住这次登出也无所谓：本机已经没有 token 了。
    }
  }, [session]);

  return {
    user: session?.user ?? null,
    accessToken: session?.accessToken ?? null,
    status: (session ? "signed-in" : "anonymous") as AccountStatus,
    busy,
    error,
    devCode,
    signInWithDeveloper,
    sendCode,
    signInWithCode,
    signOut,
  };
}

export type InkflowAccount = ReturnType<typeof useInkflowAccount>;
